// [S4] Three-portal family features — My Doctor: current doctor + Head
// directory search and request.
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class MyDoctorScreen extends ConsumerWidget {
  const MyDoctorScreen({super.key});

  Future<void> _request(BuildContext context, WidgetRef ref, String familyId, String doctorId) async {
    try {
      await ref.read(familyPortalApiProvider).requestFamilyDoctor(
        familyId: familyId,
        doctorId: doctorId,
      );
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Request sent to the doctor.')),
        );
      }
    } on Object {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not send the request. There may already be one pending.'),
          ),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) => Scaffold(
    appBar: AppBar(title: const Text('My Doctor')),
    body: SafeArea(
      child: ref
          .watch(familyDashboardProvider)
          .when(
            loading: () => const LoadingStateView(label: 'Loading'),
            error: (_, _) => ErrorRetryView(
              onRetry: () => ref.invalidate(familyDashboardProvider),
            ),
            data: (dashboard) {
              final familyId = dashboard.familyId;
              if (familyId == null) {
                return const EmptyStateView(
                  title: 'No family found',
                  message: 'Join or create a family first.',
                );
              }
              return _MyDoctorBody(
                familyId: familyId,
                isHead: dashboard.isHead,
                onRequest: _request,
              );
            },
          ),
    ),
  );
}

class _MyDoctorBody extends ConsumerWidget {
  const _MyDoctorBody({
    required this.familyId,
    required this.isHead,
    required this.onRequest,
  });

  final String familyId;
  final bool isHead;
  final Future<void> Function(BuildContext, WidgetRef, String, String) onRequest;

  @override
  Widget build(BuildContext context, WidgetRef ref) => ListView(
    padding: const EdgeInsets.all(16),
    children: [
      ref
          .watch(familyDoctorProvider(familyId))
          .when(
            loading: () => const LoadingStateView(label: 'Loading doctor'),
            error: (_, _) => ErrorRetryView(
              onRetry: () => ref.invalidate(familyDoctorProvider(familyId)),
            ),
            data: (doctor) => Card(
              child: ListTile(
                leading: const Icon(Icons.medical_services_outlined),
                title: Text(
                  doctor == null ? 'No family doctor yet' : 'Dr. ${doctor.displayName}',
                ),
                subtitle: Text(
                  doctor == null
                      ? 'A family doctor has not been assigned yet.'
                      : [doctor.specialty, doctor.clinic, doctor.district]
                            .whereType<String>()
                            .join(' · '),
                ),
              ),
            ),
          ),
      if (isHead) ...[
        const SizedBox(height: 24),
        const Text('Find a doctor', style: TextStyle(fontWeight: FontWeight.w700)),
        const SizedBox(height: 8),
        TextField(
          decoration: const InputDecoration(
            labelText: 'Search by name or specialty',
            prefixIcon: Icon(Icons.search),
          ),
          onChanged: (value) =>
              ref.read(doctorDirectorySearchProvider.notifier).state = value,
        ),
        const SizedBox(height: 12),
        ref
            .watch(doctorDirectoryProvider)
            .when(
              loading: () => const LoadingStateView(label: 'Searching directory'),
              error: (_, _) => ErrorRetryView(
                onRetry: () => ref.invalidate(doctorDirectoryProvider),
              ),
              data: (doctors) => doctors.isEmpty
                  ? const EmptyStateView(
                      title: 'No doctors found',
                      message: 'Try a different name, specialty or district.',
                    )
                  : Column(
                      children: doctors
                          .map(
                            (doctor) => Card(
                              child: ListTile(
                                leading: const Icon(Icons.person_outline),
                                title: Text('Dr. ${doctor.displayName}'),
                                subtitle: Text(
                                  [doctor.specialty, doctor.clinic, doctor.district]
                                      .whereType<String>()
                                      .join(' · '),
                                ),
                                trailing: TextButton(
                                  onPressed: () =>
                                      onRequest(context, ref, familyId, doctor.id),
                                  child: const Text('Request'),
                                ),
                              ),
                            ),
                          )
                          .toList(),
                    ),
            ),
      ],
    ],
  );
}
